class Solution {
public:
    int minimumLevels(vector<int>& possible) {
        int total = 0;
        for (int x : possible) total += (x == 1 ? 1 : -1);
        int prefix = 0;
        int n = possible.size();
        for (int i = 0; i < n - 1; ++i) {
            prefix += (possible[i] == 1 ? 1 : -1);
            if (2 * prefix > total) return i + 1;
        }
        return -1;
    }
};

class Solution {
    public int minimumLevels(int[] possible) {
        int total = 0;
        for (int x : possible) total += (x == 1 ? 1 : -1);
        int prefix = 0;
        int n = possible.length;
        for (int i = 0; i < n - 1; i++) {
            prefix += (possible[i] == 1 ? 1 : -1);
            if (2 * prefix > total) return i + 1;
        }
        return -1;
    }
}

var minimumLevels = function(possible) {
